/**
 * Asymmetric crypto: the runtime must produce byte-identical signatures to
 * OpenSSL, because anything else silently breaks JWTs, signed webhooks and
 * package attestations that were produced outside the browser.
 *
 * The key pair in test/fixtures was generated by Node 22's OpenSSL and is
 * committed so the comparison is reproducible; it is a test key only.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import crypto from 'node:crypto';
import { loadRuntime } from './helpers/runtime.mjs';

const privatePem = fs.readFileSync(new URL('./fixtures/rsa-2048.pem', import.meta.url), 'utf8');
const publicPem = fs.readFileSync(new URL('./fixtures/rsa-2048.pub.pem', import.meta.url), 'utf8');
const privateKey = crypto.createPrivateKey(privatePem);
const publicKey = crypto.createPublicKey(publicPem);

/** Evaluates a snippet in the runtime's global scope inside an IIFE. */
/* A block gives the snippet its own lexical scope (so `const crypto` in one
 * test cannot collide with the next) while still yielding its last expression
 * as the completion value that evaluate() returns. */
const run = (runtime, body) => runtime.evaluate('{\n' + body + '\n}');

/* Values created inside the VM have that realm's prototypes, which strict deep
 * equality rejects even when the structure matches. */
const plain = value => JSON.parse(JSON.stringify(value));

async function runtimeWithKey() {
  const runtime = await loadRuntime();
  runtime.FS['/project/private.pem'] = { c: privatePem };
  runtime.FS['/project/public.pem'] = { c: publicPem };
  return runtime;
}

test('signatures are byte-identical to OpenSSL for every supported digest', async () => {
  const runtime = await runtimeWithKey();
  for (const algorithm of ['sha1', 'sha256', 'sha384', 'sha512', 'md5']) {
    const payload = 'beownir:' + algorithm;
    const expected = crypto.sign(algorithm, Buffer.from(payload), privateKey).toString('hex');
    const actual = run(runtime, `      const crypto = require('crypto');
      const fs = require('fs');
      const key = crypto.createPrivateKey(fs.readFileSync('/project/private.pem', 'utf8'));
      crypto.sign(${JSON.stringify(algorithm)}, Buffer.from(${JSON.stringify(payload)}), key).toString('hex');
    `);
    assert.equal(actual, expected, algorithm + ' signature differs from OpenSSL');
  }
});

test('createSign matches crypto.sign, including RSA-SHA prefixed names and multiple updates', async () => {
  const runtime = await runtimeWithKey();
  const expected = crypto.sign('sha256', Buffer.from('one-two'), privateKey).toString('base64');
  const actual = run(runtime, `
    const crypto = require('crypto');
    const key = crypto.createPrivateKey(require('fs').readFileSync('/project/private.pem', 'utf8'));
    const signer = crypto.createSign('RSA-SHA256');
    signer.update('one');
    signer.update('-two');
    signer.sign(key, 'base64');
`);
  assert.equal(actual, expected);
});

test('verify accepts OpenSSL signatures and rejects tampered data or signatures', async () => {
  const good = crypto.sign('sha256', Buffer.from('payload'), privateKey);
  // PKCS#1 v1.5 is deterministic, so a "different" signature is only possible
  // by corrupting one; flipping a byte must make verification fail.
  const corrupted = Buffer.from(good);
  corrupted[corrupted.length - 1] ^= 0xff;
  const runtime = await runtimeWithKey();
  const result = run(runtime, `    const crypto = require('crypto');
    const fs = require('fs');
    const pub = crypto.createPublicKey(fs.readFileSync('/project/public.pem', 'utf8'));
    const verifier = crypto.createVerify('sha256');
    verifier.update('payload');
    [
      verifier.verify(pub, Buffer.from(${JSON.stringify(good.toString('base64'))}, 'base64')),
      crypto.verify('sha256', Buffer.from('payload'), pub, Buffer.from(${JSON.stringify(good.toString('base64'))}, 'base64')),
      crypto.verify('sha256', Buffer.from('tampered'), pub, Buffer.from(${JSON.stringify(good.toString('base64'))}, 'base64')),
      crypto.verify('sha256', Buffer.from('payload'), pub, Buffer.from(${JSON.stringify(corrupted.toString('base64'))}, 'base64')),
    ];
`);
  assert.deepEqual(plain(result), [true, true, false, false]);
});

test('RSA encryption round-trips in both directions with PKCS#1 v1.5 padding', async () => {
  const runtime = await runtimeWithKey();
  const result = run(runtime, `    const crypto = require('crypto');
    const fs = require('fs');
    const priv = crypto.createPrivateKey(fs.readFileSync('/project/private.pem', 'utf8'));
    const pub = crypto.createPublicKey(fs.readFileSync('/project/public.pem', 'utf8'));
    const sealed = crypto.publicEncrypt(pub, Buffer.from('secret payload'));
    const opened = crypto.privateDecrypt(priv, sealed);
    const signed = crypto.privateEncrypt(priv, Buffer.from('signed payload'));
    const verified = crypto.publicDecrypt(pub, signed);
    [sealed.length, opened.toString(), verified.toString()];
`);
  assert.deepEqual(plain(result), [256, 'secret payload', 'signed payload']);
});

test('OAEP with SHA-256 interoperates with OpenSSL in both directions', async () => {
  const runtime = await runtimeWithKey();
  const options = { padding: crypto.constants.RSA_PKCS1_OAEP_PADDING, oaepHash: 'sha256' };
  const fromNode = crypto.publicEncrypt({ key: publicKey, ...options }, Buffer.from('from node'));
  const runtimeOpened = run(runtime, `    const crypto = require('crypto');
    const fs = require('fs');
    const priv = crypto.createPrivateKey(fs.readFileSync('/project/private.pem', 'utf8'));
    crypto.privateDecrypt({ key: priv, padding: crypto.constants.RSA_PKCS1_OAEP_PADDING, oaepHash: 'sha256' }, Buffer.from(${JSON.stringify(fromNode.toString('base64'))}, 'base64')).toString();
`);
  assert.equal(runtimeOpened, 'from node');

  const fromRuntime = run(runtime, `    const crypto = require('crypto');
    const fs = require('fs');
    const pub = crypto.createPublicKey(fs.readFileSync('/project/public.pem', 'utf8'));
    crypto.publicEncrypt({ key: pub, padding: crypto.constants.RSA_PKCS1_OAEP_PADDING, oaepHash: 'sha256' }, Buffer.from('from runtime')).toString('base64');
`);
  const nodeOpened = crypto.privateDecrypt({ key: privateKey, ...options }, Buffer.from(fromRuntime, 'base64')).toString();
  assert.equal(nodeOpened, 'from runtime');
});

test('keys exported by the runtime are readable by OpenSSL and vice versa', async () => {
  const runtime = await runtimeWithKey();
  const exported = run(runtime, `    const crypto = require('crypto');
    const fs = require('fs');
    const key = crypto.createPrivateKey(fs.readFileSync('/project/private.pem', 'utf8'));
    ({
      pkcs1: key.export({ type: 'pkcs1', format: 'pem' }),
      pkcs8: key.export({ type: 'pkcs8', format: 'pem' }),
      spki: crypto.createPublicKey(key).export({ type: 'spki', format: 'pem' }),
      publicPkcs1: crypto.createPublicKey(key).export({ type: 'pkcs1', format: 'pem' }),
      jwk: key.export({ format: 'jwk' }),
      details: key.asymmetricKeyDetails,
    });
`);
  assert.equal(exported.pkcs8, privatePem);
  assert.equal(exported.spki, publicPem);
  assert.equal(crypto.createPrivateKey(exported.pkcs1).asymmetricKeyType, 'rsa');
  assert.equal(crypto.createPublicKey(exported.publicPkcs1).asymmetricKeyType, 'rsa');
  assert.deepEqual(exported.jwk.kty, 'RSA');
  assert.equal(crypto.createPrivateKey({ key: exported.jwk, format: 'jwk' }).export({ type: 'pkcs8', format: 'pem' }), privatePem);
  assert.equal(exported.details.modulusLength, 2048);
  assert.equal(exported.details.publicExponent, 65537);
});

test('unsupported asymmetric features fail loudly instead of returning wrong bytes', async () => {
  /* createECDH now works for the NIST prime curves (see crypto.test.mjs for the
   * OpenSSL-oracle tests); an unknown curve name must still fail loudly, which
   * is what the second outcome checks. */
  const runtime = await runtimeWithKey();
  const result = run(runtime, `    const crypto = require('crypto');
    const fs = require('fs');
    const key = crypto.createPrivateKey(fs.readFileSync('/project/private.pem', 'utf8'));
    const outcome = fn => { try { fn(); return 'no-throw'; } catch (error) { return error instanceof Error && error.message ? 'threw' : 'bad-error'; } };
    const codeOf = fn => { try { fn(); return 'no-throw'; } catch (error) { return error.code || error.name; } };
    ({
      outcomes: [
        outcome(() => crypto.sign('sha256', Buffer.from('x'), { key, padding: crypto.constants.RSA_PKCS1_PSS_PADDING })),
        outcome(() => crypto.createECDH('not-a-curve')),
        outcome(() => crypto.createSign('RSA-SHA256').sign({ key, padding: crypto.constants.RSA_PKCS1_PSS_PADDING }, 'hex')),
        outcome(() => crypto.createPrivateKey('not a key')),
        outcome(() => crypto.publicEncrypt(crypto.createPublicKey(key), Buffer.alloc(300))),
        outcome(() => crypto.publicEncrypt(crypto.createPublicKey(key), Buffer.alloc(4), { padding: crypto.constants.RSA_NO_PADDING })),
      ],
      pssCode: codeOf(() => crypto.sign('sha256', Buffer.from('x'), { key, padding: crypto.constants.RSA_PKCS1_PSS_PADDING })),
      badKeyCode: codeOf(() => crypto.createPrivateKey('not a key')),
      digestCode: codeOf(() => crypto.createSign('sha3-999').sign(key)),
      tooLargeCode: codeOf(() => crypto.publicEncrypt(crypto.createPublicKey(key), Buffer.alloc(300))),
      pssConstant: crypto.constants.RSA_PKCS1_PSS_PADDING,
    });
`);
  assert.deepEqual(plain(result).outcomes, ['threw', 'threw', 'threw', 'threw', 'threw', 'threw']);
  assert.equal(result.pssCode, 'ERR_CRYPTO_OPERATION_FAILED');
  assert.equal(result.badKeyCode, 'ERR_OSSL_UNSUPPORTED');
  assert.equal(result.digestCode, 'ERR_CRYPTO_INVALID_DIGEST');
  assert.equal(result.tooLargeCode, 'ERR_OSSL_RSA_DATA_TOO_LARGE_FOR_KEY_SIZE');
  assert.equal(result.pssConstant, 6);
});
